// Rosenbrock 10: CMA-ES of rule 6.4, `Cmaes` with its defaults (4 + 3 ln n samples, the best half
// recombined with positive log weights, Hansen's 2016 learning rates, a mean drawn uniformly in
// the box, an initial step of 0.3 of each range) and no restarts (`Restarts::Never`, the default,
// set explicitly). A sample outside the box is drawn again, up to 100 times, and then clipped
// (rule 2.4)
fn run_rosenbrock(args: &Args, seed: u64) -> Result<()> {
    let bounds = -5.0..=10.0;
    let inside = |genome: &Reals| genome.iter().all(|x| bounds.contains(x));
    let build = |seed| {
        Cmaes::builder(Real::uniform(args.size, bounds.clone())?)
            .restarts(cmaes::Restarts::Never)
            .minimize()
            .seed(seed)
            .build()
    };
    solve(
        args,
        seed,
        "cma_es",
        Some(REAL_TARGET),
        build,
        rosenbrock,
        inside,
    )
}

def bounded_evaluate(budget, function, low, high, size):
    """The fitness function within the box, with DEAP's documented constraint handling
    (tutorials/advanced/constraints, "Constraint Handling"), as its box-bounded ES example
    examples/es/cma_mo.py does (cma.Strategy has no bounds): tools.ClosestValidPenalty evaluates a
    sample outside the box at its closest point inside (each gene clipped) and adds 1e6 times the
    squared distance to it. A sample inside the box is evaluated as it is. The counter is around the
    fitness function itself, inside DEAP's repair: it sees the evaluated point, so `outside` is 0 by
    construction (rule 2.4)."""
    lower, upper = numpy.full(size, low), numpy.full(size, high)

    def valid(individual):
        return not (any(individual < lower) or any(individual > upper))

    def closest_feasible(individual):
        return numpy.minimum(upper, numpy.maximum(lower, numpy.array(individual)))

    def distance(feasible_ind, original_ind):
        return sum((f - o) ** 2 for f, o in zip(feasible_ind, original_ind))

    toolbox = base.Toolbox()
    toolbox.register("evaluate", budget.wrap(function))
    toolbox.decorate("evaluate", tools.ClosestValidPenalty(valid, closest_feasible, 1.0e6, distance))
    return toolbox

def solve(method, seed, counter, size, problem_name):
    """Runs the method once, until the target, the budget or the time cap, and returns why it
    ended otherwise (rules 2.2 and 8.4): the pycma criterion that ended CMAES, or None. CMAES
    also ends, with no criterion, on any error pycma raises (its _advance catches them all)."""
    function, lower, upper, _ = PROBLEMS[problem_name]
    algorithm, run_seed = method(size, seed)
    termination = BudgetTermination(counter)
    np.random.seed(run_seed)
    try:
        minimize(CountedProblem(counter, function, size, lower, upper), algorithm, termination,
                 seed=run_seed, verbose=False, copy_algorithm=False, copy_termination=False)
    except Stop:
        pass
    if counter.reached() or counter.out_of_budget():
        return None
    stopped = termination.pycma and dict(termination.pycma.stop(check=False))
    if stopped:
        return "pycma's " + ", ".join(sorted(stopped))
    return "the algorithm ended with no stop criterion (for CMAES: an error in pycma)"

static long cmaes(Budget budget, RealProblem problem, int size, String[] endedBy) {
    double[] mean = new double[size];
    for (int i = 0; i < size; i++) mean[i] = JMetalRandom.getInstance().nextDouble(problem.lower, problem.upper);
    var cmaes = new CovarianceMatrixAdaptationEvolutionStrategy.Builder(problem)
        .setLambda(10)
        .setSigma(4.5)
        .setTypicalX(mean)
        .setMaxEvaluations(Integer.MAX_VALUE)
        .build();
    seedCmaes(cmaes, JMetalRandom.getInstance().nextInt(0, Integer.MAX_VALUE - 1));
    try {
        cmaes.run();
        endedBy[0] = "checkEigenCorrectness";
    } catch (Stop stop) {
        // the target, the budget or the time cap
    } catch (ArrayIndexOutOfBoundsException crash) {
        endedBy[0] = "tql2 ArrayIndexOutOfBoundsException";
    }
    // λ evaluations a generation, the initial population included
    budget.fixedGenerations(10);
    return budget.evaluations / 10;
}

static void seedCmaes(CovarianceMatrixAdaptationEvolutionStrategy cmaes, long seed) {
    try {
        Field field = CovarianceMatrixAdaptationEvolutionStrategy.class.getDeclaredField("rand");
        field.setAccessible(true);
        field.set(cmaes, new Random(seed));
    } catch (ReflectiveOperationException error) {
        throw new IllegalStateException(error);
    }
}
